What does this print?

```rust
use std::collections::HashMap;

fn main() {
    let words = ["apple", "avocado", "banana", "blueberry", "cherry"];
    let mut m: HashMap<char, usize> = HashMap::new();
    for w in words {
        *m.entry(w.chars().next().unwrap()).or_insert(0) += w.len();
    }
    println!("{}", m[&'b']);
}
```

